{"id": "v19/lexical-group/platform_label", "version": 1, "symbol": "platform_label", "kind": "lexical_group", "status": "Accepted", "definition": "A source-supplied name of a software platform, service, framework, library, package, build tool or operating system (platform_label::django, platform_label::windows). Denotes that named system only; no version, vendor, capability or relation between systems is implied.", "not": "The project being edited when the source does not say so (a repository named platform_label::django is code_entity/software_version context), a programming-language feature, or a file format.", "group": {"key_form": "lower_identifier", "examples": ["platform_label::django", "platform_label::windows", "platform_label::pytorch_lightning"], "key_aliases": {"sklearn": "scikit_learn", "macosx": "macos", "osx": "macos", "win": "windows", "gcp": "gcloud"}, "recognition": ["Spell the key as the source's name in lower case with underscores for spaces or hyphens (scikit-learn -> scikit_learn, PyTorch Lightning -> pytorch_lightning)."]}, "shared_rules": ["v19/rule/lexical-groups"]}
